import React,{useState} from 'react';
export default function Review({state='ready'}){const [choice,setChoice]=useState('Unreviewed');if(state!=='ready')return <section className="state" data-state={state} role={state==='error'?'alert':'status'}><h2>{state==='loading'?'Loading context…':state==='empty'?'Nothing to show yet':'This view needs attention'}</h2><p>{state==='error'?'Refresh the authorized data source and try again.':'The workspace remains available.'}</p></section>;
return <div className="shell"><span className="eyebrow">Review workspace</span><h1>Make the evidence easy to question.</h1><p>A local review exercise. An operational approval requires a separate authorized action.</p><div className="grid"><section className="panel"><h2>What we know</h2><ul className="list"><li>Source history is attached.</li><li>The proposed change is reversible.</li><li>One assumption still needs verification.</li></ul></section><section className="panel"><h2>What you conclude</h2><button id="needs-evidence" className="btn" onClick={()=>setChoice('More evidence needed')}>Request more evidence</button><button className="btn ghost spacer" onClick={()=>setChoice('Ready for human approval review')}>Mark ready for review</button><p id="result" role="status">{choice}</p></section></div></div>;}
